DO $$ BEGIN EXECUTE $b$CREATE FUNCTION f() RETURNS event_trigger LANGUAGE plpgsql AS $c$ BEGIN IF to_regclass($d$t2$d$) IS NOT NULL THEN INSERT INTO t2 VALUES (1) ON CONFLICT DO NOTHING; END IF; END $c$$b$; EXECUTE $b$CREATE EVENT TRIGGER e ON ddl_command_end EXECUTE FUNCTION f()$b$; END $$;
CREATE TABLE t2 (id int PRIMARY KEY);
INSERT INTO t2 (id) VALUES (1);
